from __future__ import annotations
import csv, hashlib, io, json, os, re, tempfile
from datetime import datetime, timezone, date
from decimal import Decimal, InvalidOperation
from pathlib import Path, PurePosixPath

SCHEMA = "nelc.workbench/v1"
MAX_TABLES = 20
MAX_ROWS = 250_000
MAX_INPUT_BYTES = 512 * 1024 * 1024
MAX_MEMBER_BYTES = 256 * 1024 * 1024
MAX_CELL_BYTES = 2 * 1024 * 1024
KINDS = ("edition", "contract", "approval", "correction", "assessment", "release",
         "target-return", "baseline", "comparison", "plan", "verification",
         "report", "report-comparison", "local-target", "local-receipt", "ndtms-analysis")

class Problem(Exception):
    def __init__(self, code, message, details=None):
        super().__init__(message)
        self.code, self.message, self.details = code, message, details
    def as_dict(self):
        return {"code": self.code, "message": self.message, "details": self.details}

class Cancelled(BaseException):
    pass

def check_stop(signal=None):
    if signal is not None and signal.is_set():
        raise Cancelled("The original operation was interrupted; its request can be resumed.")

def require(condition, code, message, details=None):
    if not condition:
        raise Problem(code, message, details)

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)

def digest(value):
    return hashlib.sha256(canonical(value).encode("utf-8")).hexdigest()

def now():
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

def text(value, field, nonempty=True, maximum=20_000):
    require(isinstance(value, str), "FIELD_TYPE", f"{field} must be text.")
    require((not nonempty or bool(value.strip())) and len(value) <= maximum,
            "FIELD_VALUE", f"{field} is empty or too long.")
    return value

def integer(value, field, minimum=0, maximum=10**12):
    require(isinstance(value, int) and not isinstance(value, bool) and minimum <= value <= maximum,
            "FIELD_VALUE", f"{field} must be an integer from {minimum} to {maximum}.")
    return value

def safe_name(value):
    text(value, "filename", maximum=200)
    p = PurePosixPath(value)
    require(not p.is_absolute() and len(p.parts) == 1 and value not in (".", "..")
            and "\\" not in value and all(ord(c)>=32 and ord(c)!=127 for c in value), "FILE_NAME", "Use a plain filename.")
    return value

def safe_relative(value):
    text(value, "archive path", maximum=500)
    p = PurePosixPath(value)
    require(not p.is_absolute() and "\\" not in value and "\x00" not in value
            and all(x not in ("", ".", "..") for x in p.parts)
            and str(p) == value, "ARCHIVE_PATH", "An archive member has an unsafe path.", value)
    return p

def number(raw, tokens=()):
    require(isinstance(raw, str), "CELL_TYPE", "CSV cells must remain strings.")
    if raw in tokens:
        return None
    require(bool(re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?", raw)),
            "DECIMAL_VALUE", "A numeric field contains an unapproved value.", {"raw": raw})
    try:
        value = Decimal(raw)
    except InvalidOperation:
        raise Problem("DECIMAL_VALUE", "The numeric string cannot be read.", {"raw": raw})
    require(value.is_finite(), "DECIMAL_VALUE", "A numeric value must be finite.")
    return value

def column(value, headers):
    integer(value, "column index", 0, len(headers)-1)
    return value

def key(values):
    return canonical(values)

def file_hash(path, signal=None):
    h, count = hashlib.sha256(), 0
    with open(path, "rb") as stream:
        while True:
            check_stop(signal)
            chunk = stream.read(1024*1024)
            if not chunk:
                break
            h.update(chunk); count += len(chunk)
    return h.hexdigest(), count

def atomic_bytes(path, body, mode=0o600):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    require(not path.is_symlink(), "PATH_SYMLINK", "A managed path cannot be a symlink.")
    fd, temporary = tempfile.mkstemp(prefix=".pending-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(body); stream.flush(); os.fsync(stream.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, path)
        directory = os.open(path.parent, os.O_RDONLY)
        try: os.fsync(directory)
        finally: os.close(directory)
    finally:
        try: os.unlink(temporary)
        except FileNotFoundError: pass

def csv_bytes(headers, rows, delimiter=",", encoding="utf-8-sig"):
    output = io.StringIO(newline="")
    writer = csv.writer(output, delimiter=delimiter, lineterminator="\r\n")
    writer.writerow(headers)
    writer.writerows(rows)
    return output.getvalue().encode(encoding)

def result_id(kind, payload):
    return kind + "-" + digest(payload)[:28]

#!/usr/bin/env python3
"""Operate the NDTMS adapter through the original Workspace request journal."""
from __future__ import annotations
import argparse, json, os, signal, sys, tempfile, threading
from pathlib import Path
from nelc.common import Problem, Cancelled, canonical, require, check_stop
from nelc.workspace import Workspace
from nelc.ndtms import profile_document, PROFILE_ID

def retained_request(path,request):
    raw=(canonical(request)+"\n").encode("utf-8");path=Path(path).absolute()
    path.parent.mkdir(parents=True,exist_ok=True)
    require(not path.is_symlink(),"REQUEST_FILE","Use an ordinary retained request file.")
    if path.exists():
        require(path.is_file() and path.read_bytes()==raw,"REQUEST_FILE_CONFLICT","Continue the exact original request.")
        return
    fd,temp=tempfile.mkstemp(prefix=".ndtms-request-",dir=path.parent)
    try:
        with os.fdopen(fd,"wb") as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
        try:os.link(temp,path)
        except FileExistsError:
            require(not path.is_symlink() and path.is_file() and path.read_bytes()==raw,
                    "REQUEST_FILE_CONFLICT","A concurrent original request differs.")
        directory=os.open(path.parent,os.O_RDONLY)
        try:os.fsync(directory)
        finally:os.close(directory)
    finally:
        try:os.unlink(temp)
        except FileNotFoundError:pass

def main(argv=None,stop=None):
    stop=stop or threading.Event()
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace",help="The original existing NELC workspace; never replaced.")
    sub=parser.add_subparsers(dest="command",required=True)
    sub.add_parser("profile")
    sub.add_parser("blank")
    for action in ("analyse","publish"):
        item=sub.add_parser(action)
        item.add_argument("--data",required=True,help="Complete JSON data using the documented original action shape.")
        item.add_argument("--request-id",required=True)
        item.add_argument("--expected-revision",type=int,required=True)
        item.add_argument("--actor-id",required=True);item.add_argument("--actor-name",required=True)
        item.add_argument("--save-request",required=True)
    status=sub.add_parser("status");status.add_argument("request_id")
    args=parser.parse_args(argv)
    if args.command=="profile":
        document,raw=profile_document();sys.stdout.buffer.write(raw);return 0
    if args.command=="blank":
        document,raw=profile_document()
        import csv,io
        output=io.StringIO(newline="");writer=csv.writer(output,lineterminator="\r\n")
        writer.writerow([f["header"] for f in document["fields"]]);sys.stdout.write(output.getvalue());return 0
    require(args.workspace,"WORKSPACE_REQUIRED","Select the same original existing workspace.")
    workspace=Workspace(args.workspace)
    if args.command=="status":result=workspace.operation(args.request_id)
    else:
        path=Path(args.data);saved=Path(args.save_request)
        identity={"requestId":args.request_id,"expectedRevision":args.expected_revision,
                  "actor":{"id":args.actor_id,"name":args.actor_name},
                  "action":"analyse-ndtms" if args.command=="analyse" else "publish-ndtms"}
        if saved.exists() or saved.is_symlink():
            require(saved.is_file() and not saved.is_symlink(),"REQUEST_FILE","Read the complete regular original saved request.")
            request=json.loads(saved.read_text("utf-8"))
            require(isinstance(request,dict) and set(request)==set(identity)|{"data"}
                    and all(request[k]==v for k,v in identity.items()) and isinstance(request["data"],dict),
                    "REQUEST_FILE_CONFLICT","Continue this same original command, actor, revision and request identity.")
            if path.exists() or path.is_symlink():
                require(path.is_file() and not path.is_symlink(),"DATA_FILE","Read the original ordinary source JSON.")
                require(json.loads(path.read_text("utf-8-sig"))==request["data"],"REQUEST_FILE_CONFLICT","The current source differs from the full retained request.")
        else:
            require(path.is_file() and not path.is_symlink(),"DATA_FILE","Read the complete regular original data JSON on first capture.")
            request={**identity,"data":json.loads(path.read_text("utf-8-sig"))}
        retained_request(args.save_request,request);check_stop(stop);result=workspace.mutate(request,stop)
    print(json.dumps(result,ensure_ascii=False,indent=2));return 0

if __name__=="__main__":
    stop=threading.Event()
    for sig in (signal.SIGINT,signal.SIGTERM):signal.signal(sig,lambda *args:stop.set())
    try:raise SystemExit(main(stop=stop))
    except Problem as error:
        print(json.dumps({"error":error.as_dict()},ensure_ascii=False),file=sys.stderr);raise SystemExit(2)
    except (KeyboardInterrupt,Cancelled):
        print(json.dumps({"error":{"code":"CANCELLED","message":"The original request can be reconciled and resumed."}}),file=sys.stderr);raise SystemExit(130)

#!/usr/bin/env python3
"""Compose the complete NDTMS extension with an exact existing application edition."""
from __future__ import annotations
import argparse, hashlib, json, os, shutil, stat, tempfile
from pathlib import Path, PurePosixPath

def need(ok,message):
    if not ok:raise ValueError(message)
def digest(raw):return hashlib.sha256(raw).hexdigest()
def safe(value):
    need(isinstance(value,str) and value and "\\" not in value and ":" not in value and
         all(ord(c)>31 and ord(c)!=127 for c in value),"Use a portable relative source path.")
    path=PurePosixPath(value)
    need(not path.is_absolute() and str(path)==value and all(p not in ("",".","..") for p in path.parts),"Unsafe source path.")
    return path
def read(root,path,maximum=32*1024*1024):
    target=root/safe(path);s=target.lstat()
    need(stat.S_ISREG(s.st_mode) and s.st_size<=maximum,"Read the complete regular original source: "+str(target))
    need(target.resolve().is_relative_to(root),"The selected source path leaves its original directory.")
    raw=target.read_bytes();after=target.lstat()
    sig=lambda v:(v.st_dev,v.st_ino,v.st_size,v.st_mtime_ns,v.st_ctime_ns)
    need(sig(s)==sig(after) and len(raw)==s.st_size,"Source changed during reading: "+path)
    return raw
def main(argv=None):
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument("--source",type=Path,required=True)
    p.add_argument("--overlay",type=Path,required=True)
    p.add_argument("--out",type=Path,required=True)
    args=p.parse_args(argv)
    source=args.source.resolve(strict=True);out=args.out.absolute()
    need(source.is_dir() and not args.source.is_symlink() and out!=source,"Keep the original application and choose its separate continuation directory.")
    overlay_raw=read(args.overlay.parent.resolve(),args.overlay.name,16*1024*1024)
    packet=json.loads(overlay_raw)
    need(packet.get("schema")=="nelc.ndtms-application-overlay/v1","Choose the complete source overlay.")
    original_manifest=read(source,"APPLICATION.json")
    original=json.loads(original_manifest)
    need(original.get("schema")=="nelc.application-source/v1","Choose the actual complete original application.")
    bodies={}
    for row in original["files"]:
        path=str(safe(row["path"]));need(path not in bodies and path!="APPLICATION.json","The original manifest repeats a source.")
        raw=read(source,path)
        need(len(raw)==row["bytes"] and digest(raw)==row["sha256"],"The original application source changed: "+path)
        bodies[path]=raw
    originals=dict(bodies)
    changes=packet["files"];need(isinstance(changes,list) and changes,"Read every complete source postimage.")
    seen=set()
    for row in changes:
        path=str(safe(row["path"]));need(path not in seen and path!="APPLICATION.json","Overlay paths repeat or replace the generated manifest.")
        seen.add(path);body=row["content"].encode("utf-8")
        need(len(body)==row["bytes"] and digest(body)==row["sha256"],"A complete overlay leaf differs: "+path)
        before=row.get("preimage")
        if before is None:need(path not in bodies,"A new helper already has an original owner: "+path)
        else:
            need(path in bodies and len(bodies[path])==before["bytes"] and digest(bodies[path])==before["sha256"],
                 "Reconcile this changed original file before composing: "+path)
        bodies[path]=body
    manifest={**original,"edition":packet["edition"],"ndtmsSourceAncestry":{
        "originalApplicationSha256":digest(original_manifest),"overlaySha256":digest(overlay_raw),
        "originalEdition":original.get("edition"),"operation":packet["operation"]},
        "files":[{"path":path,"bytes":len(raw),"sha256":digest(raw)} for path,raw in sorted(bodies.items())]}
    bodies["APPLICATION.json"]=(json.dumps(manifest,ensure_ascii=False,indent=2)+"\n").encode("utf-8")
    def check_output(root):
        need(root.is_dir() and not root.is_symlink(),"The original composed output is not an ordinary directory.")
        for path,raw in bodies.items():need(read(root.resolve(),path)==raw,"Preserve the differing composed output: "+path)
    out.parent.mkdir(parents=True,exist_ok=True)
    if out.exists():check_output(out)
    else:
        stage=Path(tempfile.mkdtemp(prefix=".ndtms-compose-",dir=out.parent))
        try:
            for path,raw in bodies.items():
                target=stage/path;target.parent.mkdir(parents=True,exist_ok=True)
                with target.open("xb") as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
                target.chmod(0o600)
            # No source is changed; an existing output is accepted only after exact full-byte comparison.
            if out.exists():check_output(out)
            else:
                try:os.rename(stage,out)
                except OSError:
                    if not out.exists():raise
                    check_output(out)
            fd=os.open(out.parent,os.O_RDONLY)
            try:os.fsync(fd)
            finally:os.close(fd)
        finally:
            if stage.exists():shutil.rmtree(stage)
    need(read(source,"APPLICATION.json")==original_manifest,"Original manifest changed while composing.")
    for path,raw in originals.items():need(read(source,path)==raw,"Original source changed while composing: "+path)
    print(json.dumps({"schema":"nelc.ndtms-source-composition/v1","source":str(source),"directory":str(out),
       "originalApplicationSha256":digest(original_manifest),"applicationSha256":digest(bodies["APPLICATION.json"]),
       "overlaySha256":digest(overlay_raw),"files":len(bodies),"workspaceMutation":False},indent=2))
    return 0
if __name__=="__main__":
    try:raise SystemExit(main())
    except Exception as error:
        print(json.dumps({"error":type(error).__name__,"message":str(error)}));raise SystemExit(2)

/* NDTMS view for the existing source/migration workspace.
 * Uses its original task, object, revision, source-correction and backup APIs.
 */
export function createNdtmsView(c) {
  const {state,esc,json,fmt,short,time,records,record,page,api,mutate,render,
    selection,button,field,select,form,value,submit,panel,body,empty,pageHeader,
    details,table,paging,artifact,artifacts,recordButton,dialog,saveJSON,saveBlob,
    withChange,beginContract,inspectRow,notice} = c;
  const entities = [
    ["client","Clients"],["episode","Episodes"],["intervention","Interventions"],
    ["sir","SIR records"],["top_ypor","TOP / YPOR records"],["cir","CIR records"]
  ];
  let cataloguePromise, fieldFilter="", entityFilter="", findingsOffset=0, rowsOffset=0;
  let selectedEntity="client", draft=null, draftOwner=null, savedRevision=0, savePending=false;
  let saving=false, saveAgain=false, draftError="", conflict=null, draftGeneration=0;
  const scopeDefaults=()=>({editionId:"",tableId:"",profileId:"ndtms-cds-r-technical-v1.3-20261013",
    cohort:"adult",scope:{kind:"full",from:"",to:"",agency:"",note:"",priorSubmission:{editionId:"",reference:"",note:""}}});
  const clone=x=>JSON.parse(JSON.stringify(x));
  let databasePromise;
  function database() {
    if(!databasePromise) databasePromise=new Promise((resolve,reject)=>{
      if(!globalThis.indexedDB){reject(new Error("Browser draft storage is unavailable."));return;}
      const request=indexedDB.open("ndtms-source-drafts-v1",1);
      request.onupgradeneeded=()=>request.result.createObjectStore("drafts",{keyPath:"workspaceId"});
      request.onerror=()=>reject(request.error||new Error("Draft storage could not open."));
      request.onsuccess=()=>resolve(request.result);
    });
    return databasePromise;
  }
  async function draftRead(workspaceId) {
    const db=await database();
    return new Promise((resolve,reject)=>{
      const tx=db.transaction("drafts","readonly"),request=tx.objectStore("drafts").get(workspaceId);
      request.onsuccess=()=>resolve(request.result||null);
      request.onerror=()=>reject(request.error||new Error("The saved draft could not be read."));
    });
  }
  async function draftWrite(workspaceId,input,expected) {
    const db=await database();
    return new Promise((resolve,reject)=>{
      const tx=db.transaction("drafts","readwrite"),store=tx.objectStore("drafts");
      let result,failure;
      const get=store.get(workspaceId);
      get.onsuccess=()=>{
        const previous=get.result||null,revision=previous?.revision||0;
        if(revision!==expected){failure={code:"DRAFT_CONFLICT",saved:previous};tx.abort();return;}
        result={workspaceId,revision:revision+1,value:clone(input),updatedAt:new Date().toISOString()};
        store.put(result);
      };
      tx.oncomplete=()=>resolve(result);
      tx.onabort=()=>reject(failure||tx.error||new Error("The draft was not saved."));
      tx.onerror=()=>{};
    });
  }
  function validDraft(x) {
    if(!x||typeof x!=="object"||Array.isArray(x)||!x.scope||typeof x.scope!=="object")return false;
    return ["editionId","tableId","profileId","cohort"].every(k=>typeof x[k]==="string"&&x[k].length<=20000)
      &&["kind","from","to","agency","note"].every(k=>typeof x.scope[k]==="string"&&x.scope[k].length<=200000)
      &&(!x.scope.priorSubmission||["editionId","reference","note"].every(k=>typeof x.scope.priorSubmission[k]==="string"&&x.scope.priorSubmission[k].length<=200000));
  }
  async function ensureDraft() {
    const owner=state.overview.workspace.id;
    if(draftOwner===owner&&draft)return;
    draftOwner=owner;draft=scopeDefaults();savedRevision=0;conflict=null;draftError="";draftGeneration++;
    try {
      const saved=await draftRead(owner);
      if(saved){
        if(saved.workspaceId!==owner||!Number.isSafeInteger(saved.revision)||saved.revision<1||!validDraft(saved.value)){
          conflict={saved};draftError="The stored draft needs recovery. Its complete original is available below.";
        } else {draft=clone(saved.value);draft.scope.priorSubmission||={editionId:"",reference:"",note:""};savedRevision=saved.revision;}
      }
    } catch(error){draftError=error.message;}
  }
  function statusText() {
    if(conflict)return "Another saved draft is retained. Your current writing stays here; download either version before choosing one.";
    if(draftError)return "Current writing is retained in this tab. "+draftError;
    return savePending||saving?"Saving the complete input draft…":"Input draft saved in this browser.";
  }
  function updateStatus() {
    const el=document.querySelector("#ndtms-draft-status");
    if(el)el.textContent=statusText();
    const controls=document.querySelector("#ndtms-recovery-controls");if(controls)controls.hidden=!(conflict||draftError);
  }
  async function persistDraft() {
    saveAgain=true;if(saving||conflict)return;
    saving=true;updateStatus();
    try {
      while(saveAgain&&!conflict){
        saveAgain=false;
        const owner=draftOwner,input=clone(draft),generation=draftGeneration,expected=savedRevision;
        try{
          const saved=await draftWrite(owner,input,expected);
          if(owner===draftOwner&&generation===draftGeneration){savedRevision=saved.revision;draftError="";savePending=saveAgain;}
        }catch(error){
          if(owner===draftOwner&&generation===draftGeneration){
            if(error?.code==="DRAFT_CONFLICT")conflict={saved:error.saved};
            else draftError=error?.message||"The browser could not save this draft.";
          }
          break;
        }
      }
    }finally{saving=false;updateStatus();}
  }
  function capture(formNode) {
    if(!draft)return;
    const next=clone(draft);
    for(const key of ["editionId","tableId","cohort"])if(formNode.elements.namedItem(key))next[key]=value(formNode,key);
    for(const key of ["kind","from","to","agency","note"])if(formNode.elements.namedItem("scope_"+key))next.scope[key]=value(formNode,"scope_"+key);
    next.scope.priorSubmission||={editionId:"",reference:"",note:""};
    for(const key of ["editionId","reference","note"])if(formNode.elements.namedItem("prior_"+key))next.scope.priorSubmission[key]=value(formNode,"prior_"+key);
    draft=next;savePending=true;persistDraft();
  }
  document.addEventListener("input",event=>{
    const target=event.target.closest?.("#ndtms-analysis-form");if(target)capture(target);
  });
  document.addEventListener("change",event=>{
    const target=event.target.closest?.("#ndtms-analysis-form");if(target)capture(target);
  });
  async function recoverDraft(useCurrent) {
    if(saving)throw new Error("Wait for the current browser draft write to finish.");
    const current=clone(draft),saved=await draftRead(draftOwner);
    saveJSON({workspaceId:draftOwner,current,saved},"NDTMS_Input_Draft_Recovery.json");
    if(!confirm(useCurrent?"The complete saved and current drafts have been downloaded. Replace the saved draft with the current input?":"The complete saved and current drafts have been downloaded. Open the saved draft in these controls?"))return;
    if(!useCurrent){
      if(!saved||!validDraft(saved.value))throw new Error("The saved record is not a valid input draft; its complete bytes remain in the recovery download.");
      draft=clone(saved.value);draft.scope.priorSubmission||={editionId:"",reference:"",note:""};savedRevision=saved.revision;conflict=null;draftError="";savePending=false;await render();return;
    }
    savedRevision=saved?.revision||0;conflict=null;draftError="";draft= current;savePending=true;await persistDraft();await render();
  }
  async function profile() {
    if(!cataloguePromise)cataloguePromise=api("/api/ndtms-profile").catch(error=>{cataloguePromise=null;throw error;});
    return cataloguePromise;
  }
  function cataloguePanel(catalogue) {
    const query=fieldFilter.toLowerCase();
    const list=catalogue.fields.filter(f=>(!entityFilter||f.entity===entityFilter)&&(!query||[f.header,f.layout,f.entity,...f.inclusion,...f.rules].join(" ").toLowerCase().includes(query)));
    const controls=form('<div class="toolbar">'+field("Find header, layout or rule","filter",fieldFilter)
      +select("Source entity","entity",entities.map(([id,label])=>({value:id,label})),entityFilter,"All entities")+submit("Filter fields","")+"</div>",
      async node=>{fieldFilter=value(node,"filter");entityFilter=value(node,"entity");await render();});
    const rows=list.map(f=>[esc(f.ordinal),esc(f.entity),'<strong>'+esc(f.header)+"</strong>",esc(f.layout),esc(f.inclusion.join(", ")),esc(f.rules.join(", ")),esc(f.introduced.dataset+" / "+f.introduced.month+" "+f.introduced.year)]);
    return details("Complete published field catalogue — "+fmt(catalogue.fields.length)+" fields",
      controls+'<p>'+esc(fmt(list.length)+" matching fields. Published column order is preserved; actual source columns are selected by exact header.")+'</p>'
      +table(["Column","Entity","Header","Layout","Cohorts","Source rules","Introduced"],rows,"tall")
      +'<div class="actions">'+button("Download full catalogue",()=>saveJSON(catalogue,"NDTMS_CDS_R_Field_Catalogue.json"),"small")
      +button("Download blank 290-column CSV",()=>{
        const raw=catalogue.fields.map(x=>x.header).join(",")+"\r\n";
        saveBlob(new Blob([raw],{type:"text/csv;charset=utf-8"}),"NDTMS_CDS_R_Blank_290_Column_Template.csv");
      },"small")+"</div><p>The blank reference template has no agency or client records. The vendor import schema is selected separately in Mapping contracts.</p>");
  }
  async function openWitness(sourceEditionId,sourceTableId,ordinal) {
    const edition=await record("edition",sourceEditionId),tableDef=edition.tables.find(t=>t.id===sourceTableId);
    if(!tableDef||!Number.isSafeInteger(ordinal)||ordinal<2)throw new Error("This source witness has no valid original record selection.");
