async function api(path,options={}){const headers=new Headers(options.headers||{});headers.set("Authorization","Bearer "+token);if(options.body&&typeof options.body==="string")headers.set("Content-Type","application/json");let response;
 try{response=await fetch(path,{...options,headers,cache:"no-store"});}catch(error){error.code="CONNECTION";throw error;}
 let data;const type=response.headers.get("content-type")||"";
 if(type.includes("application/json"))data=await response.json();else data=await response.text();
 if(!response.ok){const detail=data?.error||{code:"HTTP_"+response.status,message:String(data)};const e=new Error(detail.message||detail.code);Object.assign(e,detail);throw e;}return data;
}
async function refresh(){state.overview=await api("/api/overview");state.revision=state.overview.workspace.revision;state.cache.clear();state.collections.clear();$("#revision").textContent="REV "+state.revision;$("#workspace-short").textContent=short(state.overview.workspace.id);$("#workspace-name").textContent=state.overview.workspace.name;$("#actor-open").textContent=state.actor.name;}
async function records(kind){if(state.collections.has(kind))return state.collections.get(kind);let offset=0,all=[],revision=state.revision;do{const page=await api("/api/page?"+new URLSearchParams({kind,offset:String(offset),limit:"200",revision:String(revision)}));all.push(...page.items);offset=page.nextOffset;}while(offset!==null);state.collections.set(kind,all);return all;}
