async function page(kind,selection,offset=0,limit=50,revision=state.revision){return api("/api/page?"+new URLSearchParams({kind,selection:JSON.stringify(selection),offset:String(offset),limit:String(limit),revision:String(revision)}));}
async function allRows(kind,sel){let rows=[],offset=0,rev=state.revision;do{const p=await page(kind,sel,offset,200,rev);rows.push(...p.items);offset=p.nextOffset;}while(offset!==null);return rows;}
async function download(path,name){const response=await fetch(path,{headers:{Authorization:"Bearer "+token}});if(!response.ok){const r=await response.json();throw new Error(r.error?.message||"Download failed.");}const blob=await response.blob();saveBlob(blob,name);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
