function artifact(ref,label){if(!ref?.sha256)return "";return '<span class="artifact">'+button(label||ref.name||"Download",()=>download("/api/objects/"+ref.sha256+"?name="+encodeURIComponent(ref.name||label||"artifact"),ref.name||label||"artifact"),"small")+'<small>'+esc(bytes(ref.bytes))+"</small></span>";}
function artifacts(value){const refs=[],seen=new Set();function visit(x){if(!x||typeof x!=="object")return;if(x.sha256&&Number.isInteger(x.bytes)&&x.name){if(!seen.has(x.sha256)){seen.add(x.sha256);refs.push(x);}return;}if(Array.isArray(x))x.forEach(visit);else Object.values(x).forEach(visit);}visit(value);return '<div class="artifact-list">'+refs.map(r=>artifact(r)).join("")+"</div>";}
