function requestDraft(actionName,data){return {requestId:"nelc-ui-"+crypto.randomUUID(),expectedRevision:state.revision,actor:clone(state.actor),action:actionName,data};}
function pendingKey(){return "nelc-pending:"+state.overview.workspace.id;}
function pending(){try{return JSON.parse(localStorage.getItem(pendingKey())||"[]");}catch{return [];}}
function retainTask(input){const old=pending(),i=old.findIndex(x=>x.id===input.id);if(i<0)old.push(input);else if(JSON.stringify(old[i])!==JSON.stringify(input))throw new Error("An existing original task has different input.");localStorage.setItem(pendingKey(),JSON.stringify(old.slice(-100)));}
function finishTask(id){localStorage.setItem(pendingKey(),JSON.stringify(pending().filter(x=>x.id!==id)));}
function tray(task){const name=task.input?.request?.action||task.input?.kind||"Original task";$("#task-tray").className="task-tray";$("#task-tray").innerHTML="<h3>"+esc(name)+" · "+esc(task.state)+"</h3><div class=\"mono\">"+esc(task.id)+"</div>"+(["QUEUED","RUNNING"].includes(task.state)?'<div class="progress-track"></div>':"")+(task.error?'<p>'+esc(task.error.message)+"</p>":"")+'<a class="button small" href="#history">Open original task</a>';}
async function task(input,resume=false){retainTask(input);state.lastTask=input;let current;try{current=await api("/api/tasks",{method:"POST",body:JSON.stringify({...input,...(resume?{resume:true}:{})})});}catch(error){try{current=await api("/api/tasks/"+encodeURIComponent(input.id));}catch{notice("The task acknowledgement is unresolved. Its original ID and input are retained in History. "+error.message,true);throw error;}}
 while(true){tray(current);if(current.state==="COMPLETED"){finishTask(input.id);await refresh();notice("Retained "+(input.request?.action||input.kind)+" · original task "+short(input.id));setTimeout(()=>{$("#task-tray").classList.add("hidden");},4500);return current.result;}if(["FAILED","INTERRUPTED"].includes(current.state)){const e=new Error(current.error?.message||"The original task needs attention.");Object.assign(e,current.error||{});throw e;}await new Promise(resolve=>setTimeout(resolve,650));try{current=await api("/api/tasks/"+encodeURIComponent(input.id));}catch(error){notice("Connection ended while the original task was running. Reopen History to reconcile "+input.id+".",true);throw error;}}
}
async function mutate(actionName,data){const request=requestDraft(actionName,data);return (await task({id:request.requestId,kind:"operation",request})).result;}
